const config = require('./base.js').config;

config.capabilities = [
    {
        browserName: 'chrome',
        maxInstances: 1,
        browserVersion: 'stable',
        acceptInsecureCerts: true,
        'goog:chromeOptions': {
            // to run chrome headless the following flags are required
            // (see https://developers.google.com/web/updates/2017/04/headless-chrome)
            args: [
                '--window-size=1600,900',
                '--disable-gpu',
                `--lang=${process.env.browserLanguage}`,
                `--accept-lang=${process.env.browserLanguage}`,
                '--disable-web-security',
                '--disable-features=IsolateOrigins,site-per-process',
                '--headless',
            ],
            prefs: {
                'download.default_directory': process.env.downloadFolder,
            },
        },
    },
];
//Do not add the --headless option ONLY in case HEADLESS value is set to false (to avoid affecting DevOps Env runs and legacy usage)
if ('undefined' === (typeof process.env.HEADLESS).toString()) {
    process.env.HEADLESS = 'true';
}
if (!(process.env.HEADLESS == 'true')) {
    delete process.env.HEADLESS;
    config.capabilities[0]['goog:chromeOptions']['args'].pop('--headless');
}
exports.config = config;
